{"content": "     1|import { useEffect, useState } from 'react'
     2|import { createParticles } from '../../lib/animations.js'
     3|
     4|export default function VictoryOverlay({
     5|  show, winner, isDraw, lastHash, onNewGame, onReplay, onExport, moveCount,
     6|}) {
     7|  const [particlesCreated, setParticlesCreated] = useState(false)
     8|
     9|  const winnerName = winner === 1 ? '黑方' : winner === 2 ? '白方' : ''
    10|  const displayTitle = isDraw ? '平局' : `${winnerName}胜`
    11|  const shortHash = lastHash ? lastHash.substring(0, 24) + '...' : '—'
    12|
    13|  // 粒子效果
    14|  useEffect(() => {
    15|    if (show && !particlesCreated && !isDraw && winner) {
    16|      // 延迟创建粒子，配合动画时间
    17|      const timer = setTimeout(() => {
    18|        const container = document.querySelector('.victory-particles-container')
    19|        if (container) {
    20|          const cleanup = createParticles(container, {
    21|            count: 30,
    22|            colors: winner === 1 
    23|              ? ['var(--accent-primary)', '#7c3aed', '#00d4ff']
    24|              : ['var(--accent-primary)', '#00ff88', '#00d4ff'],
    25|            sizeRange: [3, 8],
    26|            duration: 1200,
    27|            spread: 150,
    28|          })
    29|          setParticlesCreated(true)
    30|          // Store cleanup for unmount
    31|          return cleanup
    32|        }
    33|      }, 400)
    34|
    35|      return () => {
    36|        clearTimeout(timer)
    37|        // If createParticles was called, its cleanup is already handled by timeout
    38|      }
    39|    }
    40|  }, [show, winner, isDraw, particlesCreated])
    41|
    42|  // 重置粒子状态
    43|  useEffect(() => {
    44|    if (!show) {
    45|      setParticlesCreated(false)
    46|    }
    47|  }, [show])
    48|
    49|  return (
    50|    <div
    51|      className={`
    52|        absolute inset-0 flex flex-col items-center justify-center
    53|        bg-paper/92 backdrop-blur-sm transition-opacity duration-500
    54|        ${show ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}
    55|      `}
    56|    >
    57|      {/* 粒子容器 */}
    58|      <div className="victory-particles-container absolute inset-0 overflow-hidden pointer-events-none" />
    59|
    60|      {/* 胜利标题 - 增强动画 */}
    61|      <div
    62|        className="font-calligraphy text-5xl text-ink tracking-[12px] relative"
    63|        style={{ 
    64|          animation: show ? 'victory-appear 0.6s cubic-bezier(0.34,1.56,0.64,1) forwards' : 'none',
    65|          transform: 'scale(3)',
    66|          opacity: 0,
    67|        }}
    68|      >
    69|        {displayTitle}
    70|        {/* 发光效果 */}
    71|        {show && (
    72|          <div 
    73|            className="absolute inset-0 font-calligraphy text-5xl tracking-[12px]"
    74|            style={{
    75|              color: 'var(--accent-primary)',
    76|              filter: 'blur(20px)',
    77|              opacity: 0.4,
    78|              animation: 'glow-pulse 2s ease-in-out infinite',
    79|            }}
    80|          >
    81|            {displayTitle}
    82|          </div>
    83|        )}
    84|      </div>
    85|
    86|      {/* 获胜棋子 - 增强动画 */}
    87|      {!isDraw && winner && (
    88|        <div
    89|          className={`w-12 h-12 rounded-full my-4 ${winner === 1 ? 'stone-black' : 'stone-white'} relative`}
    90|          style={{ 
    91|            animation: show ? 'victory-spin 0.8s cubic-bezier(0.34,1.56,0.64,1) 0.2s both' : 'none',
    92|          }}
    93|        >
    94|          {/* 棋子光环 */}
    95|          {show && (
    96|            <div 
    97|              className="absolute -inset-2 rounded-full animate-breathe"
    98|              style={{
    99|                background: 'transparent',
   100|                border: `2px solid ${winner === 1 ? 'var(--accent-secondary)' : 'var(--accent-primary)'}`,
   101|                opacity: 0.6,
   102|              }}
   103|            />
   104|          )}
   105|        </div>
   106|      )}
   107|
   108|      {/* 哈希值 */}
   109|      <div 
   110|        className="font-mono text-[10px] text-ink-faint tracking-wide mt-2 px-3 py-1.5 border border-paper-dark bg-white/50"
   111|        style={{
   112|          animation: show ? 'fade-scale-in 0.4s cubic-bezier(0.4,0,0.2,1) 0.5s both' : 'none',
   113|        }}
   114|      >
   115|        GAME HASH: {shortHash}
   116|      </div>
   117|
   118|      {/* 移动计数 */}
   119|      <div 
   120|        className="font-mono text-[9px] text-ink-faint tracking-widest mt-2"
   121|        style={{
   122|          animation: show ? 'slide-in-up 0.3s ease 0.6s both' : 'none',
   123|        }}
   124|      >
   125|        {moveCount} MOVES
   126|      </div>
   127|
   128|      {/* 按钮组 - 交错入场 */}
   129|      <div className="flex gap-3 mt-5">
   130|        <button
   131|          onClick={onNewGame}
   132|          className="px-8 py-3 bg-ink text-paper font-serif-sc text-sm tracking-[4px] hover:bg-ink-light transition-colors hover-lift"
   133|          style={{
   134|            animation: show ? 'slide-in-up 0.3s ease 0.7s both' : 'none',
   135|          }}
   136|        >
   137|          再来一局
   138|        </button>
   139|        {onReplay && moveCount > 0 && (
   140|          <button
   141|            onClick={onReplay}
   142|            className="px-8 py-3 font-serif-sc text-sm tracking-[4px] transition-colors hover-glow"
   143|            style={{
   144|              background: 'var(--bg-surface)',
   145|              border: '1px solid var(--accent-primary)',
   146|              color: 'var(--accent-primary)',
   147|              animation: show ? 'slide-in-up 0.3s ease 0.85s both' : 'none',
   148|            }}
   149|          >
   150|            回放
   151|          </button>
   152|        )}
   153|        {onExport && moveCount > 0 && (
   154|          <button
   155|            type="button"
   156|            onClick={onExport}
   157|            className="px-8 py-3 font-serif-sc text-sm tracking-[4px] transition-colors hover-glow"
   158|            style={{
   159|              background: 'var(--bg-surface)',
   160|              border: '1px solid var(--border-color)',
   161|              color: 'var(--text-secondary)',
   162|              animation: show ? 'slide-in-up 0.3s ease 1.0s both' : 'none',
   163|            }}
   164|          >
   165|            导出棋谱
   166|          </button>
   167|        )}
   168|      </div>
   169|    </div>
   170|  )
   171|}
