{"content": "     1|import { useEffect, useState } from 'react'
     2|import { createParticles } from '../../lib/animations.js'
     3|
     4|/**
     5| * GameVictory - 通用胜利覆盖层组件
     6| * 
     7| * 显示胜利/平局信息，提供操作按钮
     8| * 复用现有VictoryOverlay的动画效果
     9| */
    10|export default function GameVictory({
    11|  show,
    12|  winner,
    13|  isDraw,
    14|  lastHash,
    15|  onNewGame,
    16|  onReplay,
    17|  onExport,
    18|  moveCount,
    19|  winnerNames = { 1: '黑方', 2: '白方' },
    20|  title,
    21|  subtitle,
    22|  children,
    23|}) {
    24|  const [particlesCreated, setParticlesCreated] = useState(false)
    25|
    26|  // 确定显示的标题
    27|  const winnerName = winner ? winnerNames[winner] || `玩家${winner}` : ''
    28|  const displayTitle = title || (isDraw ? '平局' : `${winnerName}胜`)
    29|  const displaySubtitle = subtitle || ''
    30|  const shortHash = lastHash ? lastHash.substring(0, 24) + '...' : '—'
    31|
    32|  // 粒子效果
    33|  useEffect(() => {
    34|    if (show && !particlesCreated && !isDraw && winner) {
    35|      // 延迟创建粒子，配合动画时间
    36|      const timer = setTimeout(() => {
    37|        const container = document.querySelector('.victory-particles-container')
    38|        if (container) {
    39|          const cleanup = createParticles(container, {
    40|            count: 30,
    41|            colors: winner === 1 
    42|              ? ['var(--accent-primary)', '#7c3aed', '#00d4ff']
    43|              : ['var(--accent-primary)', '#00ff88', '#00d4ff'],
    44|            sizeRange: [3, 8],
    45|            duration: 1200,
    46|            spread: 150,
    47|          })
    48|          setParticlesCreated(true)
    49|          // Store cleanup for unmount
    50|          return cleanup
    51|        }
    52|      }, 400)
    53|
    54|      return () => {
    55|        clearTimeout(timer)
    56|        // If createParticles was called, its cleanup is already handled by timeout
    57|      }
    58|    }
    59|  }, [show, winner, isDraw, particlesCreated])
